"""Campaign economics. All monetary parameters are hypothetical and user-editable."""
import numpy as np
import pandas as pd


def customer_value(monthly_charges, econ):
    """Margin generated by a retained customer over the planning horizon."""
    return monthly_charges * econ["horizon_months"] * econ["gross_margin"]


def expected_net_value(probability, value, econ):
    """Expected gain of contacting a customer before knowing the outcome."""
    return probability * econ["success_rate"] * value - econ["contact_cost"]


def realized_net_value(actual, value, econ):
    """Gain of contacting a customer once the outcome is known (backtest)."""
    return actual * econ["success_rate"] * value - econ["contact_cost"]


def plan(portfolio, econ, policy="value", threshold=0.5, budget=None):
    """Return the portfolio with value columns and a boolean `contact` decision."""
    df = portfolio.copy()
    df["customer_value"] = customer_value(df["MonthlyCharges"], econ)
    df["expected_net"] = expected_net_value(df["churn_probability"], df["customer_value"], econ)
    df["realized_net"] = realized_net_value(df["actual_churn"], df["customer_value"], econ)

    if policy == "value":
        eligible = df["expected_net"] > 0
        priority = df["expected_net"]
    else:
        eligible = df["churn_probability"] >= threshold
        priority = df["churn_probability"]

    order = priority.where(eligible, -np.inf).sort_values(ascending=False).index
    ranked = [i for i in order if eligible.loc[i]]
    if budget is not None:
        ranked = ranked[: int(budget // econ["contact_cost"])]
    df["contact"] = df.index.isin(ranked)
    df["priority_rank"] = pd.Series(range(1, len(ranked) + 1), index=ranked).reindex(df.index)
    return df


def summarize(plan_df, econ):
    selected = plan_df[plan_df["contact"]]
    cost = len(selected) * econ["contact_cost"]
    expected = selected["expected_net"].sum()
    return {
        "contacts": len(selected),
        "cost": cost,
        "expected_net": expected,
        "expected_saved_customers": float((selected["churn_probability"] * econ["success_rate"]).sum()),
        "expected_roi": expected / cost if cost else 0.0,
        "realized_net": selected["realized_net"].sum(),
        "actual_churners_reached": int(selected["actual_churn"].sum()),
    }


def sensitivity(portfolio, success_rates, contact_costs, econ):
    """Expected net value of the value-based policy over a grid of assumptions."""
    value = customer_value(portfolio["MonthlyCharges"].to_numpy(), econ)
    proba = portfolio["churn_probability"].to_numpy()
    grid = np.zeros((len(contact_costs), len(success_rates)))
    for i, cost in enumerate(contact_costs):
        for j, rate in enumerate(success_rates):
            net = proba * rate * value - cost
            grid[i, j] = net[net > 0].sum()
    return pd.DataFrame(grid, index=contact_costs, columns=success_rates)
